class Solution:
    def minWindow(self, s1: str, s2: str) -> str:
        n, m = len(s1), len(s2)
        INF = float('inf')
        prev = [INF] * m
        best_len, best_start = INF, 0
        for i in range(n):
            cur = [INF] * m
            if s1[i] == s2[0]:
                cur[0] = i
            else:
                cur[0] = prev[0]
            for j in range(1, m):
                if s1[i] == s2[j] and prev[j-1] != INF:
                    cur[j] = prev[j-1]
                elif prev[j] != INF:
                    cur[j] = prev[j]
            if cur[m-1] != INF:
                length = i - cur[m-1] + 1
                if length < best_len:
                    best_len, best_start = length, cur[m-1]
            prev = cur
        return "" if best_len == INF else s1[best_start:best_start+best_len]

