class Solution {
public:
    string minWindow(string s1, string s2) {
        int n = s1.size(), m = s2.size();
        const int INF = INT_MAX;
        vector<int> prev(m, INF);
        int bestLen = INF, bestStart = 0;
        for (int i = 0; i < n; i++) {
            vector<int> cur(m, INF);
            cur[0] = (s1[i] == s2[0]) ? i : prev[0];
            for (int j = 1; j < m; j++) {
                if (s1[i] == s2[j] && prev[j-1] != INF) cur[j] = prev[j-1];
                else if (prev[j] != INF) cur[j] = prev[j];
            }
            if (cur[m-1] != INF && i - cur[m-1] + 1 < bestLen) {
                bestLen = i - cur[m-1] + 1;
                bestStart = cur[m-1];
            }
            prev = move(cur);
        }
        return bestLen == INF ? "" : s1.substr(bestStart, bestLen);
    }
};

