class Solution:
    def minWindow(self, s1: str, s2: str) -> str:
        n, m = len(s1), len(s2)
        best_len, best_start = n + 1, 0
        i = j = 0
        while i < n:
            if s1[i] == s2[j]:
                j += 1
                if j == m:
                    end = i
                    t = m - 1
                    k = i
                    while t >= 0:
                        if s1[k] == s2[t]:
                            t -= 1
                        k -= 1
                    if end - k < best_len:
                        best_len, best_start = end - k, k + 1
                    j = 0
                    i = end + 1
                    continue
            i += 1
        return "" if best_len > n else s1[best_start:best_start+best_len]

