class Solution {
public:
    string minWindow(string s1, string s2) {
        int n = s1.size(), m = s2.size();
        int bestLen = n + 1, bestStart = 0;
        int i = 0, j = 0;
        while (i < n) {
            if (s1[i] == s2[j]) {
                j++;
                if (j == m) {
                    int end = i, t = m - 1, k = i;
                    while (t >= 0) {
                        if (s1[k] == s2[t]) t--;
                        k--;
                    }
                    if (end - k < bestLen) { bestLen = end - k; bestStart = k + 1; }
                    j = 0;
                    i = end + 1;
                    continue;
                }
            }
            i++;
        }
        return bestLen > n ? "" : s1.substr(bestStart, bestLen);
    }
};

